function derivedReady(c:BuildingComponent,rows:readonly BuildingComponent[],owner:Pin|undefined,registry:readonly any[]){const p=SPEC.profiles.find(p=>p.partId===c.partId);if(!p||!owner)return false;const reg=registry.find(x=>x.number===p.number),op=c.sourceFeature?.properties?.owner_shape_patch as any;return!!reg&&Object.keys(p).every(k=>JSON.stringify(reg[k])===JSON.stringify((p as any)[k]))&&rows.filter(x=>x.partId===p.partId).length===1&&c.city===p.city&&c.objectId===p.objectId&&JSON.stringify(c.origin)===JSON.stringify(p.origin)&&nativePaintSignature(c)===p.geometrySignature&&owner(c)===p.sha256&&op?.number===p.number&&op?.sourcePartId===p.sourcePartId&&op?.geometryRole===p.geometryRole;}
function groupReady(rows:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){return nativeReady(rows,leaf,programReady)&&SPEC.profiles.every(p=>{const a=rows.filter(c=>c.partId===p.partId);return a.length===1&&derivedReady(a[0],rows,owner,registry);});}
